// Package symbols is the part of the standard library that judged code may import.
//
// The go1_22_*.go files are generated by `yaegi extract` and copied unchanged (apart from the package
// name) from github.com/traefik/yaegi/stdlib. To add a package, copy its file from the Yaegi module.
// Generic packages (cmp, maps, slices) are interpreted from source instead, see ../generic.go.
package symbols

import "reflect"

// Symbols maps "import/path/name" to the package's exported symbols.
var Symbols = map[string]map[string]reflect.Value{}

// MapTypes lists functions with an interface{} parameter that behave differently when the
// argument implements some interface (fmt.Stringer, error...).
var MapTypes = map[reflect.Value][]reflect.Type{}

func init() {
	Symbols["."] = map[string]reflect.Value{"MapTypes": reflect.ValueOf(MapTypes)}
}
